import json, re, zipfile, os, shutil
from pathlib import Path

json_path=Path('/root/training_feedback.json')
work_dir=Path('/root/hwpx_work')
out_hwpx=Path('/root/training_feedback_ready.hwpx')

j=json.loads(json_path.read_text(encoding='utf-8'))

def digits_only(v):
    return ''.join(ch for ch in str(v) if ch.isdigit())

def fmt_satisfaction(v):
    s=str(v).strip()
    m=re.search(r'([0-9]+(?:\.[0-9]+)?)', s)
    score=m.group(1) if m else s
    try:
        score=f'{float(score):.1f}'
    except Exception:
        pass
    return f'{score}점 (5.0점 만점)'

def fmt_overall(v):
    base=str(v)
    suffix='후속 심화반 검토 요망.'
    if base.rstrip().endswith(suffix):
        return base
    # ensure single space before suffix
    if base and not base.endswith(' ') and not base.endswith('\n'):
        return base + ' ' + suffix
    return base + suffix

repl={}
for k,v in j.items():
    if k=='참석자수':
        repl[k]=digits_only(v)
    elif k=='만족도':
        repl[k]=fmt_satisfaction(v)
    elif k=='종합의견':
        repl[k]=fmt_overall(v)
    else:
        repl[k]=str(v)

PLACEHOLDER_RE=re.compile(r'\{\{([^{}]+)\}\}')

# Layout cache tags to remove if paragraph modified
CACHE_BLOCK_RE=re.compile(r'(?is)<\s*(?:hp|hc)\s*:\s*(?:linesegarray|linesegarray|lineSegArray)\b[^>]*>.*?<\s*/\s*(?:hp|hc)\s*:\s*(?:linesegarray|linesegarray|lineSegArray)\s*>')
CACHE_SELFCLOSE_RE=re.compile(r'(?is)<\s*(?:hp|hc)\s*:\s*lineseg\b[^>]*/\s*>')

# Paragraph block pattern
P_RE=re.compile(r'(?is)(<\s*hp\s*:\s*p\b[^>]*>)(.*?)(<\s*/\s*hp\s*:\s*p\s*>)')

modified_paras=0
modified_files=[]

for xml_path in sorted(work_dir.rglob('*.xml')):
    src=xml_path.read_text(encoding='utf-8')
    if '{{' not in src:
        continue

    def replace_in_para(m):
        global modified_paras
        open_tag, inner, close_tag = m.group(1), m.group(2), m.group(3)
        if '{{' not in inner:
            return m.group(0)

        def ph_sub(phm):
            key=phm.group(1)
            return repl.get(key, phm.group(0))

        new_inner=PLACEHOLDER_RE.sub(ph_sub, inner)
        if new_inner == inner:
            return m.group(0)

        # remove layout caches in modified paragraph
        cleaned=new_inner
        cleaned=CACHE_BLOCK_RE.sub('', cleaned)
        cleaned=CACHE_SELFCLOSE_RE.sub('', cleaned)
        modified_paras_local=1
        return open_tag + cleaned + close_tag

    new_src, n = P_RE.subn(replace_in_para, src)
    if new_src != src:
        xml_path.write_text(new_src, encoding='utf-8')
        modified_files.append(str(xml_path))

print('Modified XML files:')
for f in modified_files:
    print(' -', f)

# Verify no placeholders remain
remaining=[]
for xml_path in sorted(work_dir.rglob('*.xml')):
    txt=xml_path.read_text(encoding='utf-8')
    if '{{' in txt:
        # collect sample
        m=PLACEHOLDER_RE.search(txt)
        remaining.append((str(xml_path), m.group(0) if m else '??'))
if remaining:
    print('ERROR: placeholders remain')
    for p,s in remaining:
        print(p, s)
    raise SystemExit(2)

# Ensure transformed values are present somewhere (sanity)
joined='\n'.join([p.read_text(encoding='utf-8') for p in work_dir.rglob('*.xml')])
assert repl['참석자수'] in joined and '명' not in repl['참석자수']
assert repl['만족도'] in joined
assert repl['종합의견'].endswith('후속 심화반 검토 요망.')
assert repl['종합의견'] in joined

# Repackage zip
if out_hwpx.exists():
    out_hwpx.unlink()
with zipfile.ZipFile(out_hwpx, 'w', compression=zipfile.ZIP_DEFLATED) as z:
    for file_path in sorted(work_dir.rglob('*')):
        if file_path.is_dir():
            continue
        rel=file_path.relative_to(work_dir)
        # skip dotfiles
        if any(part.startswith('.') for part in rel.parts):
            continue
        z.write(file_path, arcname=str(rel))

# Validate zip integrity
with zipfile.ZipFile(out_hwpx) as z:
    bad=z.testzip()
    if bad:
        raise SystemExit(f'Zip corrupted at {bad}')
print('Wrote', out_hwpx)
